INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_ADJECTIVE','Imperial');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_ADVANCE','Unbroken Advance');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_ADVANCE_HELP','+10% Combat Strength when attacking. Retained on upgrade.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_ATTACKED_1','You have brought our next victory to us. The legions will remember your generosity.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_AURELION_HEADING_1','The Next Triumph');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_AURELION_LIVED','The Age of the Imperium');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_AURELION_NAME','Imperator Aurelion');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_AURELION_SUBTITLE','Bearer of the Unfinished Laurel');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_AURELION_TEXT_1','Aurelion earned his first command defending a river bridge and his imperial title reopening the road beyond it. He treats ceremony as a contract with the next campaign. His confidence is formidable, but he respects capable enemies and knows that an army without farms, smiths and roads cannot march on pride alone.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_AURELION_TITLES_1','Imperator');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_1','Corona Invicta');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_10','Ferrum Magna');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_11','Aquae Imperiales');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_12','Columna Regia');
