INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_24','Finis Renovatus');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_3','Aureum Forum');
