INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_7','Vallis Triumphalis');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_8','Arx Solis');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CITY_9','Nova Victoria');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CIV','The Triumphal Imperium');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CIV5_HEADING_1','One Victory Demands Another');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CIV5_TEXT_1','The Triumphal Imperium rose along the roads and river crossings of Corona Invicta. Its rulers regarded triumph as a public duty: victory proved that discipline, supply and command were aligned, and obliged them to attempt something greater. Laurel wreaths were cast in gold and set above workshops as often as palaces.[NEWLINE][NEWLINE]Success brought recruits and confidence. Conquered cities became training centers, and their captured weapons filled new Halls of Triumphs. Yet the same institutions faltered when victories ceased. No emperor could live forever on the memory of an old procession.[NEWLINE][NEWLINE]One Victory Demands Another.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_CIV_PEDIA','The Triumphal Imperium rose along the roads and river crossings of Corona Invicta. Its rulers regarded triumph as a public duty: victory proved that discipline, supply and command were aligned, and obliged them to attempt something greater. Laurel wreaths were cast in gold and set above workshops as often as palaces.[NEWLINE][NEWLINE]Success brought recruits and confidence. Conquered cities became training centers, and their captured weapons filled new Halls of Triumphs. Yet the same institutions faltered when victories ceased. No emperor could live forever on the memory of an old procession.[NEWLINE][NEWLINE]One Victory Demands Another.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_DAWN','Imperator Aurelion, the golden laurel awaits you.[NEWLINE][NEWLINE]From Corona Invicta your people have raised roads, drilled their legions and built halls for victories still to come. They ask for neither an effortless conquest nor an empty boast. They ask that success become the strength to succeed again.[NEWLINE][NEWLINE]Break the enemy line, seize the gates, and let each triumph awaken another army. But remember: when victory falls silent, confidence fades.[NEWLINE][NEWLINE]Will your Imperium carry the laurel to the ends of the earth? One Victory Demands Another.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_DEFEAT_1','The procession ends. Let history record that we marched, and that you proved the stronger.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_DUMMY','Imperial Mobilisation');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_DUMMY_HELP','Hidden military Production modifier managed by Victory Momentum.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_FRIENDLY_1','A worthy ally sharpens ambition. What shall our peoples accomplish together?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_GREETING_1','I am Aurelion, Imperator of the Triumphal Imperium. You arrive beneath the laurel of our last victory. Speak before we march toward the next.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_HALL','Hall of Triumphs');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_HALL_HELP','Replaces Barracks and preserves its normal cost, maintenance, requirements and military experience. Adds +1 Culture. At 4 or more Victory Momentum: +10% local military unit Production, additive with empire Momentum. A city conquered from a major civilization receives this actual building once Bronze Working is known; diplomatic transfers and founded cities do not qualify.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_HALL_PEDIA','Captured weapons line the marble galleries of the Hall of Triumphs. Here recruits hear the names of the fallen, artisans inspect foreign arms, and officers plan the next campaign beneath crimson standards. The institution preserves military training even in peace; its great furnaces answer only the demand of renewed victories.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_HALL_STRATEGY','Train troops in Halls and keep Momentum at 4 or higher to activate their local military industry. At 6 Momentum a Hall city receives +24% empire and +10% local military Production, totaling +34 percentage points before other normal modifiers. Civilian units, buildings and projects receive neither bonus.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_HOSTILE_1','Your words have enjoyed a longer peace than your deeds deserve.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_LEADER','Imperator Aurelion');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_LEADER_PEDIA','Aurelion earned his first command defending a river bridge and his imperial title reopening the road beyond it. He treats ceremony as a contract with the next campaign. His confidence is formidable, but he respects capable enemies and knows that an army without farms, smiths and roads cannot march on pride alone.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_MARCH','Victorious March');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_MARCH_HELP','+1 Movement for original Unbroken while their Imperium has at least 4 Victory Momentum. Lost on upgrade; never refills movement.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_MOMENTUM','Victory Momentum');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_MOMENTUM_HELP','Empire-wide military strength from current Victory Momentum.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_NEUTRAL_1','The Imperium hears you. Make your purpose clear.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_NOTICE_DECAY','A complete turn cycle passed without a qualifying victory. Victory Momentum falls to {1_Num}/6.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_NOTICE_GAIN','Victories have raised Victory Momentum to {1_Num}/6. Your armies and military workshops grow stronger.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_NOTICE_MAX','The Imperium stands at maximum Victory Momentum: 6/6. +12% military Combat Strength and +24% military Production. One Victory Demands Another.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_NOTICE_TITLE','Victory Begets Victory');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_PEACE_1','Let our soldiers rest and our smiths work. The laurel does not wither in a single day.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_PEACE_OFFER_1','We have measured one another. Accept peace, and let each empire prepare its own future.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SHORT','Triumphal Imperium');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_1','Cassian');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_10','Octavia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_2','Valeria');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_3','Drusus');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_4','Livia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_5','Corvin');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_6','Severa');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_7','Marcellus');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_8','Aelia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_SPY_9','Vigil');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_STRATEGY','Prepare a normal economy, Iron supply and army before fighting. Chain victories against major civilizations to build Momentum; defensive kills also sustain it. At 4 Momentum, original Unbroken gain 1 Movement and Halls gain +10% local military Production. Choose Domination, but preserve units and Happiness: Momentum fades during unsuccessful campaigns or peace.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_TRADE_1','Agreed. Our roads shall carry the terms of this bargain.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_TRAIT','Victory Begets Victory');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_TRAIT_HELP','Earn Victory Momentum (0-6): +1 for defeating a major civilization military unit in combat; +2 for conquering a major civilization city. Each point grants +2% military Combat Strength and +4% military unit Production in every city. Lose 1 after a complete owner-turn cycle without a qualifying victory, including defensive victories between turns. Each city site grants conquest Momentum once per Imperium player. Conquests earn a free Hall of Triumphs after Bronze Working.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UI_ACTIVE','[COLOR_POSITIVE_TEXT]ACTIVE[ENDCOLOR]');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UI_EFFECTS','Strength +{1_Num}%   Military Production +{2_Num}%');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UI_INACTIVE','INACTIVE (requires 4)');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UI_TIP','Victory Momentum: {1_Num}/6[NEWLINE]Combat Strength: +{2_Num}%[NEWLINE]Military unit Production in all cities: +{3_Num}%[NEWLINE]Unbroken - Victorious March (+1 Movement): {4_Status}[NEWLINE]Hall of Triumphs (+10% local military Production): {4_Status}[NEWLINE][NEWLINE]+1 per major military combat kill; +2 per first conquest of a major city site. No rewards from barbarians, City-States or civilians. Each complete owner-turn cycle without a qualifying victory loses 1. Victories between turns count. Hover here for current effects.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UI_TITLE','VICTORY MOMENTUM: {1_Num} / 6');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UNIT','The Unbroken');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UNIT_HELP','Replaces Swordsman, retaining its active cost, Strength, Iron requirement, Movement and technology. Unbroken Advance: +10% attacking Combat Strength, retained on upgrade. At 4 or more Victory Momentum, original Unbroken gain +1 Movement; this temporary effect is removed below 4 and on upgrade. Activating it never refills movement.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UNIT_PEDIA','The Unbroken carry the marks of every campaign on shields passed from veteran to recruit. Their name is an obligation rather than a promise of invulnerability. They advance because the soldier beside them advances, and every laurel on a standard records a victory that must be surpassed.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_UNIT_STRATEGY','Use these elite infantry offensively alongside ranged support. Their permanent attack bonus survives upgrading; Victorious March belongs only to the original Unbroken type. They still need Iron, healing, good terrain and protection against concentrated fire.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_TRI_WAR_1','The road to our next triumph passes through your gates. Prepare your armies.');
